func findTaskByID(tasks []*Task, id int) *Task {
	for _, task := range tasks {
		if task.ID == id {
			return task
		}
	}
	return nil
}

func filterTasks(tasks []*Task, statuses map[string]bool, q Query) []*Task {
	var out []*Task
	for _, task := range tasks {
		if len(statuses) > 0 && !statuses[task.Status] {
			continue
		}
		if matchesQuery(task, q) {
			out = append(out, task)
		}
	}
	if statuses["resolved"] && len(statuses) == 1 {
		sortResolvedTasks(out)
	} else {
		sortOpenTasks(out)
	}
	return out
}

func buildTask(base *Task, context Query, q Query, status string, preserveCreated bool) *Task {
	task := &Task{
		Priority:     "P2",
		DelegatedTo:  "",
		Subtasks:     []string{},
		Dependencies: []string{},
		Created:      time.Now().UTC(),
		Resolved:     zeroTime(),
		Due:          zeroTime(),
		Tags:         []string{},
	}
	if base != nil {
		task = copyTask(base)
	}
	if !preserveCreated || base == nil {
		task.Created = time.Now().UTC()
	}
	if base == nil {
		task.Resolved = zeroTime()
		if task.Due.IsZero() {
			task.Due = zeroTime()
		}
	}
	applyContextToTask(task, context)
	applyCreateQuery(task, q)
	task.Status = status
	if task.Priority == "" {
		task.Priority = "P2"
	}
	if status != "resolved" {
		task.Resolved = zeroTime()
	}
	return task
}

func parseTaskYAML(data []byte) (*Task, error) {
	task := &Task{
		Tags:         []string{},
		Subtasks:     []string{},
		Dependencies: []string{},
		DelegatedTo:  "",
		Project:      "",
		Priority:     "P2",
		Notes:        "",
		Due:          zeroTime(),
		Resolved:     zeroTime(),
	}
	lines := strings.Split(strings.ReplaceAll(string(data), "\r\n", "\n"), "\n")
	for i := 0; i < len(lines); i++ {
		line := lines[i]
		if strings.TrimSpace(line) == "" {
			continue
		}
		switch {
		case strings.HasPrefix(line, "summary:"):
			task.Summary = parseScalar(strings.TrimSpace(strings.TrimPrefix(line, "summary:")))
		case strings.HasPrefix(line, "notes:"):
			rest := strings.TrimSpace(strings.TrimPrefix(line, "notes:"))
			if strings.HasPrefix(rest, "|") {
				i++
				var noteLines []string
				for i < len(lines) {
					if strings.HasPrefix(lines[i], "  ") {
						noteLines = append(noteLines, strings.TrimPrefix(lines[i], "  "))
						i++
						continue
					}
					if lines[i] == "" {
						noteLines = append(noteLines, "")
						i++
						continue
					}
					i--
					break
				}
				task.Notes = strings.Join(noteLines, "\n")
			} else {
				task.Notes = parseScalar(rest)
			}
		case strings.HasPrefix(line, "tags:"):
			rest := strings.TrimSpace(strings.TrimPrefix(line, "tags:"))
			if rest == "[]" {
				task.Tags = []string{}
				continue
			}
			var tags []string
			for i+1 < len(lines) && strings.HasPrefix(lines[i+1], "- ") {
				i++
				tags = append(tags, strings.TrimPrefix(lines[i], "- "))
			}
			task.Tags = tags
		case strings.HasPrefix(line, "project:"):
			task.Project = parseScalar(strings.TrimSpace(strings.TrimPrefix(line, "project:")))
		case strings.HasPrefix(line, "priority:"):
			task.Priority = parseScalar(strings.TrimSpace(strings.TrimPrefix(line, "priority:")))
		case strings.HasPrefix(line, "delegatedto:"):
			task.DelegatedTo = parseScalar(strings.TrimSpace(strings.TrimPrefix(line, "delegatedto:")))
		case strings.HasPrefix(line, "subtasks:"):
			task.Subtasks = parseInlineList(strings.TrimSpace(strings.TrimPrefix(line, "subtasks:")))
		case strings.HasPrefix(line, "dependencies:"):
			task.Dependencies = parseInlineList(strings.TrimSpace(strings.TrimPrefix(line, "dependencies:")))
		case strings.HasPrefix(line, "created:"):
			task.Created = parseTime(strings.TrimSpace(strings.TrimPrefix(line, "created:")))
		case strings.HasPrefix(line, "resolved:"):
			task.Resolved = parseTime(strings.TrimSpace(strings.TrimPrefix(line, "resolved:")))
		case strings.HasPrefix(line, "due:"):
			task.Due = parseTime(strings.TrimSpace(strings.TrimPrefix(line, "due:")))
		}
	}
	return task, nil
}

func parseScalar(s string) string {
	if s == `""` {
		return ""
	}
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		unquoted, err := strconv.Unquote(s)
		if err == nil {
			return unquoted
		}
	}
	return s
}

func parseInlineList(s string) []string {
	if s == "[]" {
		return []string{}
	}
	return []string{}
}

func parseTime(s string) time.Time {
	if s == "" {
		return zeroTime()
	}
	t, err := time.Parse(time.RFC3339Nano, s)
	if err != nil {
		return zeroTime()
	}
	return t.UTC()
}

func renderTaskYAML(task *Task) []byte {
	var b strings.Builder
	fmt.Fprintf(&b, "summary: %s\n", yamlScalar(task.Summary))
	writeNotes(&b, task.Notes)
	writeStringList(&b, "tags", task.Tags)
	fmt.Fprintf(&b, "project: %s\n", yamlScalar(task.Project))
	fmt.Fprintf(&b, "priority: %s\n", yamlScalar(task.Priority))
	fmt.Fprintf(&b, "delegatedto: %s\n", yamlScalar(task.DelegatedTo))
	fmt.Fprintf(&b, "subtasks: []\n")
	fmt.Fprintf(&b, "dependencies: []\n")
	fmt.Fprintf(&b, "created: %s\n", task.Created.UTC().Format(time.RFC3339Nano))
	fmt.Fprintf(&b, "resolved: %s\n", task.Resolved.UTC().Format(time.RFC3339Nano))
	fmt.Fprintf(&b, "due: %s\n", task.Due.UTC().Format(time.RFC3339Nano))
	return []byte(b.String())
}

func yamlScalar(value string) string {
	if value == "" {
		return `""`
	}
	if strings.ContainsAny(value, "\"\t\r") ||
		strings.Contains(value, ": ") ||
		strings.HasPrefix(value, "- ") ||
		strings.HasPrefix(value, "#") ||
		strings.HasPrefix(value, "[") ||
		strings.HasPrefix(value, "{") ||
		strings.HasPrefix(value, " ") ||
		strings.HasSuffix(value, " ") ||
		value == "null" ||
		value == "true" ||
		value == "false" {
		return strconv.Quote(value)
	}
	return value
}

func writeNotes(b *strings.Builder, notes string) {
	switch {
	case notes == "":
		fmt.Fprintf(b, "notes: %s\n", yamlScalar(notes))
	case strings.Contains(notes, "\n"):
		if strings.HasPrefix(notes, "\n") {
			fmt.Fprintf(b, "notes: |2-\n")
		} else {
			fmt.Fprintf(b, "notes: |-\n")
		}
		for _, line := range strings.Split(notes, "\n") {
			if line == "" {
				fmt.Fprintln(b)
			} else {
				fmt.Fprintf(b, "  %s\n", line)
			}
		}
	default:
		fmt.Fprintf(b, "notes: %s\n", yamlScalar(notes))
	}
}

func writeStringList(b *strings.Builder, key string, values []string) {
	if len(values) == 0 {
		fmt.Fprintf(b, "%s: []\n", key)
		return
	}
	fmt.Fprintf(b, "%s:\n", key)
	for _, value := range values {
		fmt.Fprintf(b, "- %s\n", value)
	}
}

func newUUID() string {
	var buf [16]byte
	if _, err := io.ReadFull(rand.Reader, buf[:]); err != nil {
		now := time.Now().UnixNano()
		return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x", now>>32, (now>>16)&0xffff, now&0xffff, now&0xffff, now)
	}
	buf[6] = (buf[6] & 0x0f) | 0x40
	buf[8] = (buf[8] & 0x3f) | 0x80
	return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x",
		uint32(buf[0])<<24|uint32(buf[1])<<16|uint32(buf[2])<<8|uint32(buf[3]),
		uint16(buf[4])<<8|uint16(buf[5]),
		uint16(buf[6])<<8|uint16(buf[7]),
		uint16(buf[8])<<8|uint16(buf[9]),
		buf[10:16],
	)
}

func tempEditPath(id int, summary, ext string) string {
	return filepath.Join(os.TempDir(), fmt.Sprintf("dstask.%d.%d-%s.%s", time.Now().UnixNano(), id, slugifySummary(summary), ext))
}

func runEditor(path string) error {
	editor := os.Getenv("EDITOR")
	if editor == "" {
		editor = os.Getenv("VISUAL")
	}
	if editor == "" {
		editor = "vi"
	}
	cmd := exec.Command(editor, path)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

func openURL(url string) error {
	var cmd *exec.Cmd
	switch runtime.GOOS {
	case "darwin":
		cmd = exec.Command("open", url)
	case "windows":
		cmd = exec.Command("cmd", "/c", "start", url)
	default:
		cmd = exec.Command("xdg-open", url)
	}
	return cmd.Run()
}
